output application/json

// Guardamos la validación de MongoDB en una variable bohemia para legibilidad
var isSuccessfullyRegistered = (payload.result.ok == 1) and (payload.result.n >= 1)

var originalEmail = vars.originalRequest.customer.email default ""
---
{
  "codeResponse": payload.codigo,
  "messageResponse": if (isSuccessfullyRegistered) "operacion realizada exitosamente" else "No se pudo actualizar el cliente",
  ("customer": {
    "idp": {
      "creationDate": vars.fechaActual."\$date",
      "id": vars.responseCreateUserGcp.localId
    },
    "mail": originalEmail
  }) if (isSuccessfullyRegistered)
}

